INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15930, 'AIIMS Board Rules Twisha Sharma''s Death a Suicide', 'एम्स बोर्ड ने कहा, त्विशा शर्मा की मौत आत्महत्या से हुई', 'An AIIMS medical board has concluded that Twisha Sharma died by suicide. The board''s findings, reported by multiple outlets, state there were no signs of assault. The conclusion was reached after an examination by the medical board.', 'एम्स के एक मेडिकल बोर्ड ने यह निष्कर्ष निकाला है कि त्विशा शर्मा की मौत आत्महत्या से हुई। कई आउटलेट्स द्वारा रिपोर्ट किए गए बोर्ड के निष्कर्षों में कहा गया है कि हमले के कोई संकेत नहीं थे। यह निष्कर्ष मेडिकल बोर्ड द्वारा की गई जांच के बाद निकाला गया।', '["AIIMS medical board determined Twisha Sharma''s death was by suicide.", "The board found no evidence of assault.", "The conclusion was based on an examination by the medical board."]'::jsonb, '["एम्स मेडिकल बोर्ड ने निर्धारित किया कि त्विशा शर्मा की मौत आत्महत्या से हुई।", "बोर्ड को हमले का कोई सबूत नहीं मिला।", "यह निष्कर्ष मेडिकल बोर्ड द्वारा की गई जांच पर आधारित था।"]'::jsonb, 'Crime & Law', 'India', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["National Herald"], "owners": ["National Herald"]}, "center": {"count": 1, "sources": ["The Tribune"], "owners": ["The Tribune"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "National Herald", "owner": "National Herald", "lean": "left", "language": "en", "url": "https://news.google.?oc=5", "headline": "AIIMS medical board concludes Twisha Sharma died by suicide"}, {"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Twisha Sharma died by suicidal hanging, AIIMS board finds; no signs of assault"}]'::jsonb, '{"title": "AIIMS Board Rules Twisha Sharma''s Death a Suicide", "summary": "An AIIMS medical board has concluded that Twisha Sharma died by suicide. The board''s findings, reported by multiple outlets, state there were no signs of assault. The conclusion was reached after an examination by the medical board.", "summary_points": ["AIIMS medical board determined Twisha Sharma''s death was by suicide.", "The board found no evidence of assault.", "The conclusion was based on an examination by the medical board."], "title_hi": "एम्स बोर्ड ने कहा, त्विशा शर्मा की मौत आत्महत्या से हुई", "summary_hi": "एम्स के एक मेडिकल बोर्ड ने यह निष्कर्ष निकाला है कि त्विशा शर्मा की मौत आत्महत्या से हुई। कई आउटलेट्स द्वारा रिपोर्ट किए गए बोर्ड के निष्कर्षों में कहा गया है कि हमले के कोई संकेत नहीं थे। यह निष्कर्ष मेडिकल बोर्ड द्वारा की गई जांच के बाद निकाला गया।", "summary_points_hi": ["एम्स मेडिकल बोर्ड ने निर्धारित किया कि त्विशा शर्मा की मौत आत्महत्या से हुई।", "बोर्ड को हमले का कोई सबूत नहीं मिला।", "यह निष्कर्ष मेडिकल बोर्ड द्वारा की गई जांच पर आधारित था।"], "framing": {}, "framing_hi": {}, "topic": "Crime & Law", "region": "India", "published_at": null, "image_url": "", "sources": [{"source": "National Herald", "owner": "National Herald", "lean": "left", "language": "en", "url": "https://news.google.?oc=5", "headline": "AIIMS medical board concludes Twisha Sharma died by suicide"}, {"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Twisha Sharma died by suicidal hanging, AIIMS board finds; no signs of assault"}], "coverage": {"left": {"count": 1, "sources": ["National Herald"], "owners": ["National Herald"]}, "center": {"count": 1, "sources": ["The Tribune"], "owners": ["The Tribune"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.476185'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15929, 'Tamil Nadu Minister Vows to Block Harmful Hydrocarbon Projects', 'तमिलनाडु के मंत्री ने हानिकारक हाइड्रोकार्बन परियोजनाओं को रोकने की कसम खाई', 'Tamil Nadu Minister for Environment, Climate Change, and Forests, Thiru. Siva V. Meyyanathan, stated that the state government will not permit any hydrocarbon projects that negatively impact the public. He made this statement in response to concerns raised about the proposed ONGC gas exploration project in the Cauvery delta region. The minister assured that the government is committed to protecting the interests of the people and the environment.', 'पर्यावरण, जलवायु परिवर्तन और वन मंत्री, थिरु. शिव वी. मेयनाथन ने कहा कि राज्य सरकार किसी भी हाइड्रोकार्बन परियोजना की अनुमति नहीं देगी जो जनता पर नकारात्मक प्रभाव डालती हो। उन्होंने कावेरी डेल्टा क्षेत्र में प्रस्तावित ओएनजीसी गैस अन्वेषण परियोजना के बारे में उठाई गई चिंताओं के जवाब में यह बयान दिया। मंत्री ने आश्वासन दिया कि सरकार लोगों के हितों और पर्यावरण की रक्षा के लिए प्रतिबद्ध है।', '["Tamil Nadu Minister Thiru. Siva V. Meyyanathan stated the government will not allow projects negatively impacting people.", "The statement was made in the context of a proposed ONGC gas exploration project in the Cauvery delta region.", "The minister assured protection for public interests and the environment.", "The government''s stance is to prevent harmful projects."]'::jsonb, '["तमिलनाडु के मंत्री थिरु. शिव वी. मेयनाथन ने कहा कि सरकार ऐसे प्रोजेक्ट्स की अनुमति नहीं देगी जो लोगों पर नकारात्मक प्रभाव डालते हों।", "यह बयान कावेरी डेल्टा क्षेत्र में प्रस्तावित ओएनजीसी गैस अन्वेषण परियोजना के संबंध में उठाई गई चिंताओं के जवाब में दिया गया था।", "मंत्री ने जनता के हितों और पर्यावरण की सुरक्षा का आश्वासन दिया।", "सरकार का रुख हानिकारक परियोजनाओं को रोकना है।"]'::jsonb, 'Environment', 'India', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Deccan Chronicle"], "owners": ["Deccan Chronicle"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMikgFBVV95cUxOb050NUMtYnhLbkhhUHp5YlFyTHBaemREaTF3dkkzQ05ZRU9mdHFxaDZIeVFIMXhTU1U2UXhjUk96Skx5Rk1RWDhoTVVscnRiX3RON3c4STZJazRfR2JJV00ydHE3enF1dDNOOXFmOTBLVlYyNThLNHdTM2JLaW5WR1UxN0xqVDhaQjJRZHRFNTBVQQ?oc=5", "headline": "Hydrocarbon project: TN govt wont allow projects negatively..."}, {"source": "Deccan Chronicle", "owner": "Deccan Chronicle", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Won’t Allow Projects Negatively Impacting People, TN Minister on Hydrocarbon Project"}]'::jsonb, '{"title": "Tamil Nadu Minister Vows to Block Harmful Hydrocarbon Projects", "summary": "Tamil Nadu Minister for Environment, Climate Change, and Forests, Thiru. Siva V. Meyyanathan, stated that the state government will not permit any hydrocarbon projects that negatively impact the public. He made this statement in response to concerns raised about the proposed ONGC gas exploration project in the Cauvery delta region. The minister assured that the government is committed to protecting the interests of the people and the environment.", "summary_points": ["Tamil Nadu Minister Thiru. Siva V. Meyyanathan stated the government will not allow projects negatively impacting people.", "The statement was made in the context of a proposed ONGC gas exploration project in the Cauvery delta region.", "The minister assured protection for public interests and the environment.", "The government''s stance is to prevent harmful projects."], "title_hi": "तमिलनाडु के मंत्री ने हानिकारक हाइड्रोकार्बन परियोजनाओं को रोकने की कसम खाई", "summary_hi": "पर्यावरण, जलवायु परिवर्तन और वन मंत्री, थिरु. शिव वी. मेयनाथन ने कहा कि राज्य सरकार किसी भी हाइड्रोकार्बन परियोजना की अनुमति नहीं देगी जो जनता पर नकारात्मक प्रभाव डालती हो। उन्होंने कावेरी डेल्टा क्षेत्र में प्रस्तावित ओएनजीसी गैस अन्वेषण परियोजना के बारे में उठाई गई चिंताओं के जवाब में यह बयान दिया। मंत्री ने आश्वासन दिया कि सरकार लोगों के हितों और पर्यावरण की रक्षा के लिए प्रतिबद्ध है।", "summary_points_hi": ["तमिलनाडु के मंत्री थिरु. शिव वी. मेयनाथन ने कहा कि सरकार ऐसे प्रोजेक्ट्स की अनुमति नहीं देगी जो लोगों पर नकारात्मक प्रभाव डालते हों।", "यह बयान कावेरी डेल्टा क्षेत्र में प्रस्तावित ओएनजीसी गैस अन्वेषण परियोजना के संबंध में उठाई गई चिंताओं के जवाब में दिया गया था।", "मंत्री ने जनता के हितों और पर्यावरण की सुरक्षा का आश्वासन दिया।", "सरकार का रुख हानिकारक परियोजनाओं को रोकना है।"], "framing": {}, "framing_hi": {}, "topic": "Environment", "region": "India", "published_at": null, "image_url": "", "sources": [{"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMikgFBVV95cUxOb050NUMtYnhLbkhhUHp5YlFyTHBaemREaTF3dkkzQ05ZRU9mdHFxaDZIeVFIMXhTU1U2UXhjUk96Skx5Rk1RWDhoTVVscnRiX3RON3c4STZJazRfR2JJV00ydHE3enF1dDNOOXFmOTBLVlYyNThLNHdTM2JLaW5WR1UxN0xqVDhaQjJRZHRFNTBVQQ?oc=5", "headline": "Hydrocarbon project: TN govt wont allow projects negatively..."}, {"source": "Deccan Chronicle", "owner": "Deccan Chronicle", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Won’t Allow Projects Negatively Impacting People, TN Minister on Hydrocarbon Project"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Deccan Chronicle"], "owners": ["Deccan Chronicle"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.452569'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15928, 'Congress Chief Defends Vande Mataram Recitation Amid Controversy', 'कांग्रेस प्रमुख ने वंदे मातरम गायन पर उठे विवाद पर किया बचाव', 'Congress President Mallikarjun Kharge stated that the Vande Mataram he recited was the same one sung by Mahatma Gandhi and Jawaharlal Nehru. He also mentioned that Atal Bihari Vajpayee had sung the same version. This statement comes amidst a controversy surrounding the singing of the national song.', 'कांग्रेस अध्यक्ष मल्लिकार्जुन खरगे ने कहा कि उन्होंने वही वंदे मातरम गाया जो महात्मा गांधी और जवाहरलाल नेहरू गाते थे। उन्होंने यह भी कहा कि अटल बिहारी वाजपेयी ने भी वही संस्करण गाया था। यह बयान राष्ट्रगान के गायन को लेकर उठे विवाद के बीच आया है।', '["Congress President Mallikarjun Kharge defended his recitation of Vande Mataram.", "Kharge claimed his version was identical to that sung by Mahatma Gandhi and Jawaharlal Nehru.", "He also stated that former Prime Minister Atal Bihari Vajpayee had sung the same version.", "The statement was made in response to a controversy over the singing of the national song."]'::jsonb, '["कांग्रेस अध्यक्ष मल्लिकार्जुन खरगे ने वंदे मातरम के अपने गायन का बचाव किया।", "खरगे ने दावा किया कि उनका संस्करण महात्मा गांधी और जवाहरलाल नेहरू द्वारा गाए गए संस्करण के समान था।", "उन्होंने यह भी कहा कि पूर्व प्रधानमंत्री अटल बिहारी वाजपेयी ने भी वही संस्करण गाया था।", "यह बयान राष्ट्रगान के गायन पर उठे विवाद के जवाब में दिया गया था।"]'::jsonb, 'Society', 'India', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Amar Ujala", "Telangana Today"], "owners": ["Amar Ujala", "Telangana Today"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Congress President Mallikarjun Kharge defended his recitation of Vande Mataram.", "Kharge cited Mahatma Gandhi, Jawaharlal Nehru, and Atal Bihari Vajpayee as having sung the same version.", "The controversy is framed around the specific version of Vande Mataram sung."]}'::jsonb, '{"center": ["कांग्रेस अध्यक्ष मल्लिकार्जुन खरगे ने वंदे मातरम के अपने गायन का बचाव किया।", "खरगे ने महात्मा गांधी, जवाहरलाल नेहरू और अटल बिहारी वाजपेयी का हवाला देते हुए कहा कि उन्होंने भी वही संस्करण गाया था।", "विवाद वंदे मातरम के गाए गए विशिष्ट संस्करण के इर्द-गिर्द केंद्रित है।"]}'::jsonb, '[{"source": "Amar Ujala", "owner": "Amar Ujala", "lean": "center", "language": "hi", "url": "https://www.amarujala.com/india-news/congress-president-mallikarjun-kharge-vande-mataram-controversy-mahatma-gandhi-jawahar-lal-nehru-2026-08-18", "headline": "Vande Mataram Row: ''मैंने वही वंदे मातरम गाया जो गांधी-नेहरू गाते थे'', विवाद पर क्या बोले मल्लिकार्जुन खरगे?"}, {"source": "Telangana Today", "owner": "Telangana Today", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMioAFBVV95cUxNNUJVRnprU3QxQWNZUFliTmJWc2VHS0NTYkMxZnFtTW1iYjNUM2JRbTNDQ01jZ1FiYTVRRC14dkc3OGx0UGt2T0RGSHpDUXBvWVF1X1FUS1Jmd25ady1jUnQtX1UxS1RQUzE3djBsdEYtWHduWGVNelp6MmpoY3R2UTNFY2JjSERZbEo0cG1WS3BzamN0OVlSYXRpR1VWM3pt?oc=5", "headline": "Vande Mataram row: We sang what Mahatma, Vajpayee sang, says Congress chief"}]'::jsonb, '{"title": "Congress Chief Defends Vande Mataram Recitation Amid Controversy", "summary": "Congress President Mallikarjun Kharge stated that the Vande Mataram he recited was the same one sung by Mahatma Gandhi and Jawaharlal Nehru. He also mentioned that Atal Bihari Vajpayee had sung the same version. This statement comes amidst a controversy surrounding the singing of the national song.", "summary_points": ["Congress President Mallikarjun Kharge defended his recitation of Vande Mataram.", "Kharge claimed his version was identical to that sung by Mahatma Gandhi and Jawaharlal Nehru.", "He also stated that former Prime Minister Atal Bihari Vajpayee had sung the same version.", "The statement was made in response to a controversy over the singing of the national song."], "title_hi": "कांग्रेस प्रमुख ने वंदे मातरम गायन पर उठे विवाद पर किया बचाव", "summary_hi": "कांग्रेस अध्यक्ष मल्लिकार्जुन खरगे ने कहा कि उन्होंने वही वंदे मातरम गाया जो महात्मा गांधी और जवाहरलाल नेहरू गाते थे। उन्होंने यह भी कहा कि अटल बिहारी वाजपेयी ने भी वही संस्करण गाया था। यह बयान राष्ट्रगान के गायन को लेकर उठे विवाद के बीच आया है।", "summary_points_hi": ["कांग्रेस अध्यक्ष मल्लिकार्जुन खरगे ने वंदे मातरम के अपने गायन का बचाव किया।", "खरगे ने दावा किया कि उनका संस्करण महात्मा गांधी और जवाहरलाल नेहरू द्वारा गाए गए संस्करण के समान था।", "उन्होंने यह भी कहा कि पूर्व प्रधानमंत्री अटल बिहारी वाजपेयी ने भी वही संस्करण गाया था।", "यह बयान राष्ट्रगान के गायन पर उठे विवाद के जवाब में दिया गया था।"], "framing": {"center": ["Congress President Mallikarjun Kharge defended his recitation of Vande Mataram.", "Kharge cited Mahatma Gandhi, Jawaharlal Nehru, and Atal Bihari Vajpayee as having sung the same version.", "The controversy is framed around the specific version of Vande Mataram sung."]}, "framing_hi": {"center": ["कांग्रेस अध्यक्ष मल्लिकार्जुन खरगे ने वंदे मातरम के अपने गायन का बचाव किया।", "खरगे ने महात्मा गांधी, जवाहरलाल नेहरू और अटल बिहारी वाजपेयी का हवाला देते हुए कहा कि उन्होंने भी वही संस्करण गाया था।", "विवाद वंदे मातरम के गाए गए विशिष्ट संस्करण के इर्द-गिर्द केंद्रित है।"]}, "topic": "Society", "region": "India", "published_at": null, "image_url": "", "sources": [{"source": "Amar Ujala", "owner": "Amar Ujala", "lean": "center", "language": "hi", "url": "https://www.amarujala.com/india-news/congress-president-mallikarjun-kharge-vande-mataram-controversy-mahatma-gandhi-jawahar-lal-nehru-2026-08-18", "headline": "Vande Mataram Row: ''मैंने वही वंदे मातरम गाया जो गांधी-नेहरू गाते थे'', विवाद पर क्या बोले मल्लिकार्जुन खरगे?"}, {"source": "Telangana Today", "owner": "Telangana Today", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMioAFBVV95cUxNNUJVRnprU3QxQWNZUFliTmJWc2VHS0NTYkMxZnFtTW1iYjNUM2JRbTNDQ01jZ1FiYTVRRC14dkc3OGx0UGt2T0RGSHpDUXBvWVF1X1FUS1Jmd25ady1jUnQtX1UxS1RQUzE3djBsdEYtWHduWGVNelp6MmpoY3R2UTNFY2JjSERZbEo0cG1WS3BzamN0OVlSYXRpR1VWM3pt?oc=5", "headline": "Vande Mataram row: We sang what Mahatma, Vajpayee sang, says Congress chief"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Amar Ujala", "Telangana Today"], "owners": ["Amar Ujala", "Telangana Today"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.424691'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15927, 'US TV Anchor Fired After Viral Newsroom Profanity Amid Lawsuit', 'अमेरिकी टीवी एंकर पर मुकदमा के बीच न्यूज रूम में अभद्र भाषा के बाद नौकरी से निकाला गया', 'Former Detroit TV anchor Taryn Asher was captured on video using profanity against her boss during a newsroom dispute. The incident occurred as Asher is suing Fox Television Stations over her termination. The station, however, states that Asher was dismissed due to alleged unprofessional conduct.', 'डेट्रॉइट की पूर्व टीवी एंकर टेरिन एशर को न्यूज रूम में अपने बॉस के खिलाफ अभद्र भाषा का इस्तेमाल करते हुए वीडियो में कैद किया गया। यह घटना तब हुई जब एशर फॉक्स टेलीविजन स्टेशंस पर अपने निकाले जाने को लेकर मुकदमा कर रही हैं। हालांकि, स्टेशन का कहना है कि एशर को कथित तौर पर अव्यवसायिक आचरण के कारण बर्खास्त किया गया था।', '["Taryn Asher, a former Detroit TV anchor, was filmed using profanity in a newsroom.", "The incident involved a heated exchange with her boss.", "Asher is currently suing Fox Television Stations over her firing.", "The station claims Asher was fired for alleged unprofessional conduct."]'::jsonb, '["डेट्रॉइट की पूर्व टीवी एंकर टेरिन एशर को न्यूज रूम में अभद्र भाषा का इस्तेमाल करते हुए फिल्माया गया था।", "इस घटना में उनके बॉस के साथ तीखी बहस हुई।", "एशर वर्तमान में अपनी बर्खास्तगी को लेकर फॉक्स टेलीविजन स्टेशंस पर मुकदमा कर रही हैं।", "स्टेशन का दावा है कि एशर को कथित तौर पर अव्यवसायिक आचरण के कारण नौकरी से निकाला गया था।"]'::jsonb, 'Crime & Law', 'World', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Mint", "The Free Press Journal"], "owners": ["HT Media", "The Free Press Journal"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Reported the incident of a US TV anchor using profanity in a newsroom.", "Noted the viral nature of the newsroom video.", "Included the detail that the anchor is suing her former employer.", "Mentioned the employer''s stated reason for termination: alleged unprofessional conduct."]}'::jsonb, '{"center": ["एक अमेरिकी टीवी एंकर द्वारा न्यूज रूम में अभद्र भाषा के इस्तेमाल की घटना की सूचना दी।", "न्यूज रूम वीडियो की वायरल प्रकृति का उल्लेख किया।", "इस बात का उल्लेख किया कि एंकर अपने पूर्व नियोक्ता पर मुकदमा कर रही है।", "नियोक्ता द्वारा बर्खास्तगी का कथित कारण बताया: कथित अव्यवसायिक आचरण।"]}'::jsonb, '[{"source": "Mint", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://www.livemint.com/news/trends/fired-us-tv-anchor-taryn-asher-calls-boss-b-in-viral-newsroom-video-amid-lawsuit-11787034453769.html", "headline": "Fired US TV anchor Taryn Asher calls boss ‘B****’ in viral newsroom video amid lawsuit"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Detroit TV Anchor Calls Her Boss ‘B**ch’ In Heated Newsroom Dispute, Fired; Video Goes Viral Amid Lawsuit"}]'::jsonb, '{"title": "US TV Anchor Fired After Viral Newsroom Profanity Amid Lawsuit", "summary": "Former Detroit TV anchor Taryn Asher was captured on video using profanity against her boss during a newsroom dispute. The incident occurred as Asher is suing Fox Television Stations over her termination. The station, however, states that Asher was dismissed due to alleged unprofessional conduct.", "summary_points": ["Taryn Asher, a former Detroit TV anchor, was filmed using profanity in a newsroom.", "The incident involved a heated exchange with her boss.", "Asher is currently suing Fox Television Stations over her firing.", "The station claims Asher was fired for alleged unprofessional conduct."], "title_hi": "अमेरिकी टीवी एंकर पर मुकदमा के बीच न्यूज रूम में अभद्र भाषा के बाद नौकरी से निकाला गया", "summary_hi": "डेट्रॉइट की पूर्व टीवी एंकर टेरिन एशर को न्यूज रूम में अपने बॉस के खिलाफ अभद्र भाषा का इस्तेमाल करते हुए वीडियो में कैद किया गया। यह घटना तब हुई जब एशर फॉक्स टेलीविजन स्टेशंस पर अपने निकाले जाने को लेकर मुकदमा कर रही हैं। हालांकि, स्टेशन का कहना है कि एशर को कथित तौर पर अव्यवसायिक आचरण के कारण बर्खास्त किया गया था।", "summary_points_hi": ["डेट्रॉइट की पूर्व टीवी एंकर टेरिन एशर को न्यूज रूम में अभद्र भाषा का इस्तेमाल करते हुए फिल्माया गया था।", "इस घटना में उनके बॉस के साथ तीखी बहस हुई।", "एशर वर्तमान में अपनी बर्खास्तगी को लेकर फॉक्स टेलीविजन स्टेशंस पर मुकदमा कर रही हैं।", "स्टेशन का दावा है कि एशर को कथित तौर पर अव्यवसायिक आचरण के कारण नौकरी से निकाला गया था।"], "framing": {"center": ["Reported the incident of a US TV anchor using profanity in a newsroom.", "Noted the viral nature of the newsroom video.", "Included the detail that the anchor is suing her former employer.", "Mentioned the employer''s stated reason for termination: alleged unprofessional conduct."]}, "framing_hi": {"center": ["एक अमेरिकी टीवी एंकर द्वारा न्यूज रूम में अभद्र भाषा के इस्तेमाल की घटना की सूचना दी।", "न्यूज रूम वीडियो की वायरल प्रकृति का उल्लेख किया।", "इस बात का उल्लेख किया कि एंकर अपने पूर्व नियोक्ता पर मुकदमा कर रही है।", "नियोक्ता द्वारा बर्खास्तगी का कथित कारण बताया: कथित अव्यवसायिक आचरण।"]}, "topic": "Crime & Law", "region": "World", "published_at": null, "image_url": "https://www.livemint.com/lm-img/img/2026/08/18/1600x900/logo/MixCollage-18-Aug-2026-12-02-PM-6394_1787034739345_1787034745157_e8a0235e-d0fe-49c4-83f7-3dba25449884.jpg", "sources": [{"source": "Mint", "owner": "HT Media", "lean": "center", "language": "en", "url": "https://www.livemint.com/news/trends/fired-us-tv-anchor-taryn-asher-calls-boss-b-in-viral-newsroom-video-amid-lawsuit-11787034453769.html", "headline": "Fired US TV anchor Taryn Asher calls boss ‘B****’ in viral newsroom video amid lawsuit"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Detroit TV Anchor Calls Her Boss ‘B**ch’ In Heated Newsroom Dispute, Fired; Video Goes Viral Amid Lawsuit"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Mint", "The Free Press Journal"], "owners": ["HT Media", "The Free Press Journal"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://www.livemint.com/lm-img/img/2026/08/18/1600x900/logo/MixCollage-18-Aug-2026-12-02-PM-6394_1787034739345_1787034745157_e8a0235e-d0fe-49c4-83f7-3dba25449884.jpg', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.399741'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_me