INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15926, 'Axis Bank Increases Credit Card Fees and Charges', 'एक्सिस बैंक ने क्रेडिट कार्ड शुल्क और प्रभारों में वृद्धि की', 'Axis Bank will implement new credit card rules effective August 28. The bank is increasing the DCC (Dynamic Currency Conversion) markup fee to 3.5%. Additionally, the maximum late payment fee will be raised to ₹1,300. New limits on reward points are also being introduced.', 'एक्सिस बैंक 28 अगस्त से नए क्रेडिट कार्ड नियम लागू करेगा। बैंक डीसीसी (डायनामिक करेंसी कन्वर्जन) मार्कअप शुल्क को 3.5% तक बढ़ा रहा है। इसके अतिरिक्त, अधिकतम विलंब भुगतान शुल्क ₹1,300 तक बढ़ा दिया जाएगा। रिवॉर्ड पॉइंट्स पर नई सीमाएं भी पेश की जा रही हैं।', '["Axis Bank credit card rules change on August 28.", "DCC markup fee will increase to 3.5%.", "Maximum late payment fee will rise to ₹1,300.", "New limits on reward points are being introduced."]'::jsonb, '["एक्सिस बैंक क्रेडिट कार्ड नियम 28 अगस्त को बदलेंगे।", "डीसीसी मार्कअप शुल्क 3.5% तक बढ़ जाएगा।", "अधिकतम विलंब भुगतान शुल्क ₹1,300 तक बढ़ जाएगा।", "रिवॉर्ड पॉइंट्स पर नई सीमाएं पेश की जा रही हैं।"]'::jsonb, 'Economy', 'India', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Business Today", "The Free Press Journal"], "owners": ["India Today Group", "The Free Press Journal"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Reported the increase in DCC markup fee to 3.5%.", "Noted the rise in maximum late payment fee to ₹1,300.", "Mentioned the introduction of new reward limits.", "Stated the effective date of the rule changes as August 28."]}'::jsonb, '{"center": ["3.5% तक डीसीसी मार्कअप शुल्क में वृद्धि की सूचना दी।", "अधिकतम विलंब भुगतान शुल्क ₹1,300 तक बढ़ने का उल्लेख किया।", "नए रिवॉर्ड सीमाओं की शुरूआत का उल्लेख किया।", "नियम परिवर्तनों की प्रभावी तिथि 28 अगस्त बताई।"]}'::jsonb, '[{"source": "Business Today", "owner": "India Today Group", "lean": "center", "language": "en", "url": "https://www.businesstoday.in/personal-finance/story/axis-bank-credit-card-rules-dcc-markup-to-rise-to-3-5-late-fee-goes-up-to-rs1300-549766-2026-08-18", "headline": "Axis Bank Credit Card rules : DCC markup to rise to 3 . 5 %, late fee goes up to ₹1 , 300"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Axis Bank Credit Card Rules Change From August 28, Higher Currency Fee & New Reward Limits Ahead"}]'::jsonb, '{"title": "Axis Bank Increases Credit Card Fees and Charges", "summary": "Axis Bank will implement new credit card rules effective August 28. The bank is increasing the DCC (Dynamic Currency Conversion) markup fee to 3.5%. Additionally, the maximum late payment fee will be raised to ₹1,300. New limits on reward points are also being introduced.", "summary_points": ["Axis Bank credit card rules change on August 28.", "DCC markup fee will increase to 3.5%.", "Maximum late payment fee will rise to ₹1,300.", "New limits on reward points are being introduced."], "title_hi": "एक्सिस बैंक ने क्रेडिट कार्ड शुल्क और प्रभारों में वृद्धि की", "summary_hi": "एक्सिस बैंक 28 अगस्त से नए क्रेडिट कार्ड नियम लागू करेगा। बैंक डीसीसी (डायनामिक करेंसी कन्वर्जन) मार्कअप शुल्क को 3.5% तक बढ़ा रहा है। इसके अतिरिक्त, अधिकतम विलंब भुगतान शुल्क ₹1,300 तक बढ़ा दिया जाएगा। रिवॉर्ड पॉइंट्स पर नई सीमाएं भी पेश की जा रही हैं।", "summary_points_hi": ["एक्सिस बैंक क्रेडिट कार्ड नियम 28 अगस्त को बदलेंगे।", "डीसीसी मार्कअप शुल्क 3.5% तक बढ़ जाएगा।", "अधिकतम विलंब भुगतान शुल्क ₹1,300 तक बढ़ जाएगा।", "रिवॉर्ड पॉइंट्स पर नई सीमाएं पेश की जा रही हैं।"], "framing": {"center": ["Reported the increase in DCC markup fee to 3.5%.", "Noted the rise in maximum late payment fee to ₹1,300.", "Mentioned the introduction of new reward limits.", "Stated the effective date of the rule changes as August 28."]}, "framing_hi": {"center": ["3.5% तक डीसीसी मार्कअप शुल्क में वृद्धि की सूचना दी।", "अधिकतम विलंब भुगतान शुल्क ₹1,300 तक बढ़ने का उल्लेख किया।", "नए रिवॉर्ड सीमाओं की शुरूआत का उल्लेख किया।", "नियम परिवर्तनों की प्रभावी तिथि 28 अगस्त बताई।"]}, "topic": "Economy", "region": "India", "published_at": null, "image_url": "https://akm-img-a-in.tosshub.com/businesstoday/images/story/202608/6a840ba5d36b7-from-august-28--gift-card-transactions-will-be-classified-separately-as-gift-card-rather-than-unde-183703959-16x9.png", "sources": [{"source": "Business Today", "owner": "India Today Group", "lean": "center", "language": "en", "url": "https://www.businesstoday.in/personal-finance/story/axis-bank-credit-card-rules-dcc-markup-to-rise-to-3-5-late-fee-goes-up-to-rs1300-549766-2026-08-18", "headline": "Axis Bank Credit Card rules : DCC markup to rise to 3 . 5 %, late fee goes up to ₹1 , 300"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Axis Bank Credit Card Rules Change From August 28, Higher Currency Fee & New Reward Limits Ahead"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Business Today", "The Free Press Journal"], "owners": ["India Today Group", "The Free Press Journal"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://akm-img-a-in.tosshub.com/businesstoday/images/story/202608/6a840ba5d36b7-from-august-28--gift-card-transactions-will-be-classified-separately-as-gift-card-rather-than-unde-183703959-16x9.png', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.376300'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15925, 'Religious Observance for Marital Bliss in Shravan Month', 'श्रावण माह में वैवाहिक सुख के लिए धार्मिक अनुष्ठान', 'The first Tuesday of the Shravan month is observed as Mangla Gauri Vrat, a religious practice dedicated to Goddess Gauri. Devotees, particularly newly married women, perform specific rituals and observe fasts to seek blessings for marital harmony and long-lasting fortune. The observance is believed to enhance love in married life and bestow unbroken good fortune. Specific उपाय (remedies/observances) are recommended for this day.', 'श्रावण माह का पहला मंगलवार मंगला गौरी व्रत के रूप में मनाया जाता है, जो देवी गौरी को समर्पित एक धार्मिक प्रथा है। विशेष रूप से नवविवाहित महिलाएं वैवाहिक सौहार्द और दीर्घकालिक सौभाग्य के लिए आशीर्वाद मांगने हेतु विशिष्ट अनुष्ठान और उपवास रखती हैं। यह व्रत दांपत्य जीवन में प्रेम बढ़ाने और अखंड सौभाग्य प्रदान करने वाला माना जाता है। इस दिन के लिए विशेष उपाय सुझाए जाते हैं।', '["The first Tuesday of the Shravan month is observed as Mangla Gauri Vrat.", "The Vrat is dedicated to Goddess Gauri.", "Newly married women are a key demographic observing this Vrat.", "The purpose is to seek blessings for marital harmony and good fortune.", "Specific rituals and remedies are associated with the observance."]'::jsonb, '["श्रावण माह का पहला मंगलवार मंगला गौरी व्रत के रूप में मनाया जाता है।", "यह व्रत देवी गौरी को समर्पित है।", "नवविवाहित महिलाएं इस व्रत का पालन करने वाली प्रमुख जनसांख्यिकी हैं।", "इसका उद्देश्य वैवाहिक सौहार्द और सौभाग्य के लिए आशीर्वाद प्राप्त करना है।", "इस व्रत से जुड़े विशिष्ट अनुष्ठान और उपाय हैं।"]'::jsonb, 'Society', 'India', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Haribhoomi", "The Free Press Journal"], "owners": ["Haribhoomi", "The Free Press Journal"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{"center": ["Highlighted the significance of the first Tuesday of Shravan as Mangla Gauri Vrat.", "Emphasized the benefits of observing the Vrat for marital bliss and good fortune.", "Mentioned specific remedies or observances recommended for the day."]}'::jsonb, '{"center": ["श्रावण के पहले मंगलवार के मंगला गौरी व्रत के महत्व पर प्रकाश डाला गया।", "वैवाहिक सुख और सौभाग्य के लिए व्रत रखने के लाभों पर जोर दिया गया।", "दिन के लिए अनुशंसित विशिष्ट उपायों या अनुष्ठानों का उल्लेख किया गया।"]}'::jsonb, '[{"source": "Haribhoomi", "owner": "Haribhoomi", "lean": "center", "language": "hi", "url": "https://news.google.com/rss/articles/CBMiswFBVV95cUxQb2NIOUJOeUJYZ2hXcGhPa0lpVlFEM21CV2NnOWZBTEhXV3VXUmltTWJyZjBpZW4yR2dhZ3VRQkRJZ0s5MEhSeFlBd2xVcTVHREVIMHZNeGV2bWpjdFloaHBUa1UxWTNQdkNSM2UwaHNkMy1fT21MSlBFWDhBRi13VnpFZUhfeHpYdllmamdsMHpKa19vbWozMDBJSFctY1pCRUpTTDZzTUo0bTFyN0lCLW5lQQ?oc=5", "headline": "Mangla Gauri Vrat 2026: आज जरूर करें ये 5 उपाय, दांपत्य जीवन में बढ़ेगा प्रेम और मिलेगा अखंड सौभाग्य का आशीर्वाद!"}, {"source": "The Free Press Journal", "owner": "The Free Press Journal", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Mangala Gauri Vrat 2026: Why The First Tuesday Of Shravan Is Special For Newly Married Women"}]'::jsonb, '{"title": "Religious Observance for Marital Bliss in Shravan Month", "summary": "The first Tuesday of the Shravan month is observed as Mangla Gauri Vrat, a religious practice dedicated to Goddess Gauri. Devotees, particularly newly married women, perform specific rituals and observe fasts to seek blessings for marital harmony and long-lasting fortune. The observance is believed to enhance love in married life and bestow unbroken good fortune. Specific उपाय (remedies/observances) are recommended for this day.", "summary_points": ["The first Tuesday of the Shravan month is observed as Mangla Gauri Vrat.", "The Vrat is dedicated to Goddess Gauri.", "Newly married women are a key demographic observing this Vrat.", "The purpose is to seek blessings for marital harmony and good fortune.", "Specific rituals and remedies are associated with the observance."], "title_hi": "श्रावण माह में वैवाहिक सुख के लिए धार्मिक अनुष्ठान", "summary_hi": "श्रावण माह का पहला मंगलवार मंगला गौरी व्रत के रूप में मनाया जाता है, जो देवी गौरी को समर्पित एक धार्मिक प्रथा है। विशेष रूप से नवविवाहित महिलाएं वैवाहिक सौहार्द और दीर्घकालिक सौभाग्य के लिए आशीर्वाद मांगने हेतु विशिष्ट अनुष्ठान और उपवास रखती हैं। यह व्रत दांपत्य जीवन में प्रेम बढ़ाने और अखंड सौभाग्य प्रदान करने वाला माना जाता है। इस दिन के लिए विशेष उपाय सुझाए जाते हैं।", "summary_points_hi": ["श्रावण माह का पहला मंगलवार मंगला गौरी व्रत के रूप में मनाया जाता है।", "यह व्रत देवी गौरी को समर्पित है।", "नवविवाहित महिलाएं इस व्रत का पालन करने वाली प्रमुख जनसांख्यिकी हैं।", "इसका उद्देश्य वैवाहिक सौहार्द और सौभाग्य के लिए आशीर्वाद प्राप्त करना है।", "इस व्रत से जुड़े विशिष्ट अनुष्ठान और उपाय हैं।"], "framing": {"center": ["Highlighted the significance of the first Tuesday of Shravan as Mangla Gauri Vrat.", "Emphasized the benefits of observing the Vrat for marital bliss and good fortune.", "Mentioned specific remedies or observances recommended for the day."]}, "framing_hi": {"center": ["श्रावण के पहले मंगलवार के मंगला गौरी व्रत के महत्व पर प्रकाश डाला गया।", "वैवाहिक सुख और सौभाग्य के लिए व्रत रखने के लाभों पर जोर दिया गया।", "दिन के लिए अनुशंसित विशिष्ट उपायों या अनुष्ठानों का उल्लेख किया गया।"]}, "topic": "Society", "region": "India", "published_at": null, "image_url": "", "sources": [{"source": "Haribhoomi", "owner": "Haribhoomi", "lean": "center", "langua